#include "asset_pack.h"
#include "screenshot_bmp.h"
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <cassert>
#include <fstream>
#include <iterator>
#include <string>
#include <vector>
#include <chrono>
#include <algorithm>
static std::vector<uint8_t> read(const std::string &p){std::ifstream f(p,std::ios::binary);assert(f);return {std::istreambuf_iterator<char>(f),{}};}
static void zlib_checks() {
 // Fixtures generated by independent Python zlib, including a final zero Adler byte.
 const std::vector<uint8_t> one={'A','P','Z','1',1,0,0,0,120,218,251,15,0,1,0,1,0};
 const std::vector<uint8_t> many={'A','P','Z','1',12,0,0,0,120,218,115,116,114,118,113,132,98,0,20,64,3,31};
 auto check=[](const std::vector<uint8_t>& packed,size_t size,bool expected){
  constexpr size_t guard=32;std::vector<uint8_t> out(size+2*guard,0xA5);
  assert(aurora_unpack(packed.data(),packed.size(),out.data()+guard,size)==expected);
  assert(std::all_of(out.begin(),out.begin()+guard,[](uint8_t x){return x==0xA5;}));
  assert(std::all_of(out.end()-guard,out.end(),[](uint8_t x){return x==0xA5;}));
  return std::vector<uint8_t>(out.begin()+guard,out.end()-guard);
 };
 assert(check(one,1,true)==std::vector<uint8_t>{255});
 const std::string reference="ABCDABCDABCD";
 assert(check(many,12,true)==std::vector<uint8_t>(reference.begin(),reference.end()));
 for(const auto& good:{one,many}) {
  const size_t size=good[4];
  for(size_t n=0;n<good.size();++n)check({good.begin(),good.begin()+n},size,false);
  auto bad=good;bad.back()^=1;check(bad,size,false); // Adler mismatch
  bad=good;bad[8]^=1;check(bad,size,false); // zlib header mismatch
  bad=good;bad.push_back(0);check(bad,size,false); // extra trailing input
  bad=good;bad.insert(bad.end(),one.begin()+8,one.end());check(bad,size,false); // second stream
  bad=good;bad[4]++;check(bad,size,false); // declared/caller size disagreement
  bad=good;bad[4]=uint8_t(size+1);check(bad,size+1,false); // actual short output
  if(size>1){bad=good;bad[4]=uint8_t(size-1);check(bad,size-1,false);} // bounded output
  bad=good;bad[4]=0;check(bad,0,false);
  bad=good;std::fill(bad.begin()+4,bad.begin()+8,255);check(bad,size,false);
  bad=good;bad[0]='X';check(bad,size,false);
 }
 assert(!aurora_unpack(nullptr,one.size(),nullptr,1));
 assert(!aurora_unpack(one.data(),one.size(),nullptr,1));
 puts("PASS: APZ1 exact pixels, all small-stream truncations (including final zero Adler), checksum/header corruption, trailing stream, forged lengths and output guard bytes");
}
int main(int argc,char **argv){
 assert(argc==3);std::string root=argv[1];
 zlib_checks();
 for(auto name:{"ui_shell","aurora_controls","aurora_dragon"}){
  auto packed=read(root+"/"+name+".pack");auto raw=read(root+"/"+name+(std::string(name)=="ui_shell"?".rgb565":".bin"));
  std::vector<uint8_t> decoded(raw.size());auto started=std::chrono::steady_clock::now();
  assert(aurora_unpack(packed.data(),packed.size(),decoded.data(),decoded.size()));assert(decoded==raw);
  printf("PASS: %s byte-for-byte identical (%zu -> %zu bytes), host decode %lld us\n",name,packed.size(),decoded.size(),(long long)std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-started).count());
  assert(!aurora_unpack(packed.data(),packed.size()-1,decoded.data(),decoded.size()));
  assert(!aurora_unpack(packed.data(),packed.size(),decoded.data(),decoded.size()-1));
  packed.push_back(0);assert(!aurora_unpack(packed.data(),packed.size(),decoded.data(),decoded.size()));
 }
 // RGB bars plus odd width exercises row padding and top-down orientation.
 FILE *f=fopen(argv[2],"wb");assert(f);const uint16_t image[]={0xf800,0x07e0,0x001f,0xffff,0,0xffe0};
 assert(screenshot_bmp(f,image,3,2));assert(fclose(f)==0);auto bmp=read(argv[2]);assert(bmp.size()==82&&bmp[0]=='B'&&bmp[1]=='M');
 assert(!screenshot_bmp(nullptr,image,3,2));puts("PASS: screenshot RGB565 masks, row padding, top-down BMP, invalid parameters; corrupt packs rejected");
}
